\textbf{Câu 7 (3,5 điểm).}[[br]]Vẽ hình đúng đến câu a.\hfill \textit{(0,25đ)}[[br]]\adjustbox{max width=0.42\linewidth}{\begin{tikzpicture}[line width=0.8pt, font=\small, scale=1.0]
